from collections import deque
def zero_one_bfs(n, g, s):
    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0
    dq = deque([s])
    while dq:
        u = dq.popleft()
        for v, w in g[u]:  # w in (0, 1)
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                (dq.appendleft if w == 0 else dq.append)(v)
    return dist

def popcount(x):
    return bin(x).count('1')  # or int.bit_count() on 3.8+/3.10+

def is_power_of_two(x):
    return x > 0 and (x & (x - 1)) == 0

def single_number(a):  # every other appears twice
    x = 0
    for v in a:
        x ^= v
    return x

